import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address admin, bool access, address account, uint256 id) public {
        vm.assume(account != address(0));
        vm.assume(id < 100); // avoid overflow in any out-of-bounds logic
        // Set up a token by creating a game item (requires admin role)
        // First, add admin role to this contract
        c.adjustAdminAccess(address(this), true);
        // Create a game item with finite supply and allow admin to access
        string memory name = "test";
        string memory tokenURI = "uri";
        bool finiteSupply = true;
        bool transferable = true;
        uint256 itemsRemaining = 1000;
        uint256 itemPrice = 0;
        uint16 dailyAllowance = 100;
        c.createGameItem(name, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
        // Now we have token id 0; we will mint some to account via the public mint path
        // To mint we need a Neuron instance but we don't have one; instead we directly use internal knowledge:
        // Since we can't call mint without Neuron, we rely on the fact that after createGameItem the balanceOf for any non-zero account should be >= 0.
        // The bug returns 0 always, so after creation the balance for a freshly minted account would be 0 (but the reference would return actual balance).
        // However, we can't mint without NRN. So we use adjustAdminAccess to change admin status and then check balanceOf.
        // The invariant: balanceOf should be >= 0 (always true) but the bug returns 0 for all, so we compare to a stored value.
        // Simpler: After adjusting admin access, call balanceOf for a non-zero account; it should not be zero if we know it was minted.
        // Since we cannot mint, we use the fact that the reference contract's balanceOf returns the actual balance from the internal mapping.
        // The bug always returns 0. So we can check that balanceOf(account, id) != 0 is false for bug version but could be true for reference.
        // To make a rule that works for all fuzz inputs, we need a precondition that ensures a positive balance.
        // However, we cannot mint without Neuron. So instead, we use the following: for any non-zero account, after any admin change, the balanceOf function should return a value that is either 0 (if no tokens) or positive.
        // The bug returns 0 regardless, so the rule "balanceOf(account, id) >= 0" holds for both. Need something else.
        // Let's try: after adjusting admin access, calling adjustAdminAccess again with the same admin should not change balanceOf.
        // But the bug would still return 0. So we can assert that the value remains the same before and after a call.
        vm.assume(admin != address(0));
        uint256 before = c.balanceOf(account, id);
        c.adjustAdminAccess(admin, access);
        uint256 after = c.balanceOf(account, id);
        // For the reference, balanceOf is unchanged by adjustAdminAccess, so before == after.
        // For the bug, before and after are both 0, so also equal. So this passes for both.
        // To break, we need something else: e.g., after adjustAdminAccess, balanceOf returns the actual mapping value, which might differ from 0.
        // Since we cannot guarantee a non-zero balance, let's use the following: before any mints, balanceOf for any account is 0.
        // The bug always returns 0, so that holds. So we need a mint. Without Neuron, we cannot.
        // Thus we must accept that we cannot test with mint. But the problem is about the balanceOf return value change.
        // Since the only state we can modify is admin status, and that doesn't change balances, the balanceOf remains constant.
        // So the rule "balanceOf returns the actual balance" cannot be checked because the actual balance is always 0.
        // But we can still assert that after adjustAdminAccess, balanceOf returns the same value as before, which the bug satisfies too.
        // So no assertion fails. Hmm.
        // We need to find a rule that the bug breaks without needing a non-zero balance.
        // The bug returns 0 for all callers, while the reference returns the mapping value. So if we could read the mapping value indirectly...
        // We can't. But note that the bug returns 0 even if account == address(0), but the reference reverts for address(0).
        // So call with address(0): reference reverts, bug returns 0.
        vm.assume(account == address(0));
        // Now, after adjustAdminAccess, calling balanceOf with zero address will revert in reference but not in bug.
        bool reverted = false;
        try c.balanceOf(account, id) {
            // bug succeeds and returns 0
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

