contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(
        address admin,
        uint256 tokenId,
        uint256 allowanceBefore,
        uint256 dailyAllowance,
        uint256 replenishTime
    ) public {
        // Bound inputs to reasonable ranges
        tokenId = bound(tokenId, 0, 10);
        allowanceBefore = bound(allowanceBefore, 0, 1000);
        dailyAllowance = bound(dailyAllowance, 0, 1000);
        replenishTime = bound(replenishTime, 0, block.timestamp + 1000);

        // Setup: first create a dummy game item (requires admin role)
        vm.assume(admin != address(0));

        // Make admin the owner to allow createGameItem
        c.transferOwnership(admin);
        vm.prank(admin);
        c.adjustAdminAccess(admin, true);

        vm.prank(admin);
        c.createGameItem(
            "TestItem",
            "ipfs://test",
            true,    // finite
            true,    // transferable
            1000,    // itemsRemaining
            10,      // itemPrice
            uint16(dailyAllowance) // dailyAllowance
        );

        // Set initial allowanceRemaining and replenishTime for a random account
        // We cannot directly set private state, so we simulate by calling mint if needed
        // Instead, we will manipulate via prank and direct set by calling _replenishDailyAllowance indirectly
        // The bug is in _replenishDailyAllowance: it does not update allowanceRemaining.
        // So we test that after adjustAdminAccess (which doesn't directly affect allowanceRemaining),
        // the property holds: allowanceRemaining is never less than what it should be.

        // The property: For any account and token, before and after adjustAdminAccess,
        // allowanceRemaining(account, tokenId) should be >= 0 (trivially) but more importantly,
        // the replenish time logic should ensure allowance is properly set.
        // Since adjustAdminAccess only changes admin status, allowanceRemaining should remain unchanged.
        // But the bug is that when _replenishDailyAllowance is called (via mint), it doesn't update allowanceRemaining.
        // So we test that calling adjustAdminAccess doesn't corrupt allowanceRemaining.

        // Record allowance before
        uint256 beforeAllowance = c.getAllowanceRemaining(admin, tokenId);

        // Call adjustAdminAccess
        vm.prank(admin);
        c.adjustAdminAccess(admin, true);

        // Record allowance after
        uint256 afterAllowance = c.getAllowanceRemaining(admin, tokenId);

        // General rule: allowance should not decrease due to adjustAdminAccess
        assertTrue(afterAllowance >= beforeAllowance, "allowanceRemaining should not decrease");
    }
}

